"""Embed web/ into include/WebAssets.h as gzip byte arrays in flash.

Runs before every ESP build (extra_scripts = pre:scripts/embed_web.py) and
standalone: python3 scripts/embed_web.py
"""
import gzip
import os

ASSETS = [
    ("WEB_INDEX_HTML", "index.html"),
    ("WEB_APP_CSS", "app.css"),
    ("WEB_APP_JS", "app.js"),
    ("WEB_ICON_SVG", "icon.svg"),
]


def generate(root):
    web = os.path.join(root, "web")
    out = os.path.join(root, "include", "WebAssets.h")
    lines = [
        "// Generated by scripts/embed_web.py from web/ — do not edit.",
        "#pragma once",
        "#include <stdint.h>",
        "#include \"Progmem.h\"",
        "",
    ]
    for name, file in ASSETS:
        with open(os.path.join(web, file), "rb") as f:
            data = gzip.compress(f.read(), compresslevel=9, mtime=0)
        body = ",".join(str(b) for b in data)
        lines.append(f"static const uint8_t {name}[] PROGMEM = {{{body}}};  // {file}, {len(data)} bytes gzip")
    text = "\n".join(lines) + "\n"
    old = open(out, encoding="utf-8").read() if os.path.exists(out) else None
    if text != old:  # keep the timestamp when nothing changed: no needless rebuilds
        with open(out, "w", encoding="utf-8") as f:
            f.write(text)


try:
    Import("env")  # noqa: F821 — provided by PlatformIO
    generate(env.subst("$PROJECT_DIR"))  # noqa: F821
except NameError:
    generate(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
